const odoo_product = $('odoo_product').first().json.product

const sku = odoo_product.sku
const price = odoo_product.price
const title = odoo_product.title
const description = odoo_product.description
// const description = "This is a sample description text that contains enough words and characters to meet the minimum length requirement of fifty symbols."
const main_image_base = odoo_product.main_image_base
const bar_code = odoo_product.ean
const brand = odoo_product.brand
const REASONS = $('CONSTANTS').first().json.CONSTANTS.ODOO.error_reason

// СПИСОК ПРОВЕРОК
const fields = [

  {
    name: 'price exists',
    is_valid: () => (
      price > 0
    ),
    error_message: 'Отсутствует цена у товара',
    error_reason: REASONS.bad_fields.value
  },

  {
    name: 'brand is not IZS',
    is_valid: () => (
      brand !== "IZS"
    ),
    error_message: 'Запрещенный бренд (IZS)',
    error_reason: REASONS.bad_fields.value
  },

  {
    name: 'shop_sku (default_code) exists',
    is_valid: () => (
      sku
    ),
    error_message: 'Отсутствует артикул (default_code)',
    error_reason: REASONS.bad_sku.value
  },

  {
    name: 'title min length',
    is_valid: () => (
      title && 
      String(title).length >= 6
    ),
    error_message: 'Название менее 6 символов',
    error_reason: REASONS.bad_fields.value
  },

  {
    name: 'title max length',
    is_valid: () => (
      String(title).length <= 140
    ),
    error_message: 'Название более 140 символов',
    error_reason: REASONS.bad_fields.value
  },

  {
    name: 'barcode (ean_main_code) exists',
    is_valid: () => (
      bar_code && 
      String(bar_code).length > 1
    ),
    error_message: 'Не указан bar_code',
    error_reason: REASONS.no_barcode.value
  },

  {
    name: 'description exists',
    is_valid: () => (
      description &&
      String(description).length >= 50
    ),
    error_message: 'Описание менее 50 символов',
    error_reason: REASONS.bad_fields.value
  },

  {
    name: 'description max length',
    is_valid: () => (
      String(description).length <= 8000
    ),
    error_message: 'Описание более 8000 символов',
    error_reason: REASONS.bad_fields.value
  },

  {
    name: 'main image exists',
    is_valid: () => (
      main_image_base && 
      String(main_image_base).length >= 10
    ),
    error_message: 'Отсутствует основное изображение',
    error_reason: REASONS.bad_fields.value
  },

  {
    name: 'brand exists',
    is_valid: () => (
      brand
    ),
    error_message: 'Отсутствует производитель',
    error_reason: REASONS.bad_fields.value
  }

]

// Запуск проверок и поиск первой ошибки
const found_field_error = fields.find(field => {
  const is_valid = field.is_valid()
  return !is_valid
})
// Возвращаем обьект, которой потом проверим на наличие ошибки по полю is_error_found
return {
  is_error_found: !!found_field_error,
  error_message: found_field_error?.error_message ?? '',
  error_reason: found_field_error?.error_reason ?? '',
}

const output = {
  "is_found_category": true,
  "category": {
    codes: $input.first().json.categories[0].codes,
    path: $input.first().json.categories[0].path
  }
}
return {output}

const attr_set_id = Number(
  $('output ').first().json.attribute_set.id
)
const available_categories = $input.first().json.available_categories
.filter(r => Number(r.attributeId) === attr_set_id)

const raw_categories = $('get_categories')
  .all()
  .map(r => r.json);

const categories = (() => {
  if (!Array.isArray(raw_categories) || raw_categories.length === 0) return [];

  // Map: categoryId -> row
  const byCatId = new Map(raw_categories.map(r => [r.data.id, r]));

  // Collect all parent_ids present
  const parentIds = new Set(
    raw_categories
      .map(r => r.data.parent_id)
      .filter(pid => pid !== null && pid !== undefined)
  );

  // Leaves: categories that never appear as a parent_id
  const leaves = raw_categories.filter(r => !parentIds.has(r.data.id));

  // Build root -> leaf path (names + ids) by walking parent chain
  const buildPathInfo = (leafRow) => {
    const names = [];
    const ids = [];
    const seen = new Set();
    let node = leafRow;

    while (node && !seen.has(node.data.id)) {
      seen.add(node.data.id);
      names.push(node.data.name);
      ids.push(node.data.id);
      const pid = node.data.parent_id ?? null;
      node = pid !== null ? byCatId.get(pid) : null;
    }

    names.reverse();
    ids.reverse();
    return { names, ids };
  };

  const out = leaves.map(leaf => {
    const { names, ids } = buildPathInfo(leaf);
    return {
      // id is now the full path of category IDs from root to this leaf
      codes: ids,
      path: names.join(' > '),
    };
  });

  out.sort((a, b) => a.path.localeCompare(b.path));
  return out;
})()
  .filter(r => {
    const path_lower = String(r.path).toLowerCase()
    const is_in_available = available_categories
    .some(av => {
      const last_categories_lower = av.lastCategories.map(last => String(last).toLowerCase())
      return last_categories_lower.some(last_lower => path_lower.endsWith(last_lower))
    })
    return is_in_available
  })

return { categories };

const available_set = $input.first().json.availables_sets

const attribute_sets = $('get_attribute_sets')
  .all()
  .map(r => r.json.data)
  .filter(r => {
    return available_set.includes(r.id)
  })



return { attribute_sets };

const attribute_set = $json.output
const is_found_attribute_set = !!$json.output?.id

return {attribute_set, is_found_attribute_set}

const pages = $input.first().json.total_pages

const result = Array.from({ length: pages }, (_, i) => {
  const page = i + 1
  return {
    json: {
      page: page
    }
  }
})

return result

const results = $input.all()

const attributes = results
.flatMap(r => {
  return r.json.attributes
})

return {attributes}

const required_attrs = $('attributes').first().json.required_attributes
.filter(r => r.IS_REQUIRED)

const found_attrs = $input.first().json.output

const found_attrs_set = new Map(
  found_attrs.map(a => [a.code, a])
)

const IS_ALL_REQUIRED_ATTRIBUTES_FOUND = required_attrs
  .every(req_attr => {
    const found = found_attrs_set.get(req_attr.code)
    // Атрибут найден в ответе AI и у него есть найденные значения
    return found && found.values.length
  })

return {IS_ALL_REQUIRED_ATTRIBUTES_FOUND}

const attributes_set_id = Number(
  $('output ').first().json.attribute_set.id
)

const attributes = $input.first().json.attributes

let required_attributes = []

attributes
  .forEach(attr => {
    // if (attr.code === "brand") return false
    const IS_REQUIRED = (() => {
      if (!attr?.required_attribute_sets) return false

      if (Array.isArray(attr.required_attribute_sets)) {
        return attr.required_attribute_sets.includes(attributes_set_id)
      }

      if (typeof attr.required_attribute_sets === 'object') {
        const attr_sets = Object.values(attr.required_attribute_sets)
        return attr_sets.includes(attributes_set_id)
      }

      return false
    })()
    required_attributes.push(
      {
        code: attr.code,
        name: attr.name,
        attribute_values: attr.attribute_values,
        value_type: attr.value_type,
        IS_REQUIRED: IS_REQUIRED
      }
    )
  })

const brand_attribute = required_attributes
  .find(attr => attr.code === "brand" && attr.IS_REQUIRED)

required_attributes = required_attributes
  .filter(attr => attr.code !== "brand")

required_attributes = required_attributes
.filter(r => r.IS_REQUIRED)



return {required_attributes, brand_attribute, attributes_set_id}

