const brand = $('odoo_product').first().json.product.brand

const brand_low_case = brand.replace("®", "").toLowerCase().trim()

const brand_attr = $('attributes').first().json.brand_attribute

const found_attr_id = brand_attr.attribute_values
  .find(v => {
    const brand_formatted = v.name.replace("®", "").toLowerCase().trim()
    return brand_formatted === brand_low_case
  })?.id

const is_found_attr_id = !!found_attr_id

// const found_attr_id = "81239"
// const is_found_attr_id = true

return {
  is_found_attr_id,
  found_attr_id
}

function removeImagesFromHTML(html) {
    // Remove all img tags
    return html.replace(/<img[^>]*>/gi, '');
}

const required_attrs_map = (() => {
  const attrs = $('attributes').first().json.required_attributes
  const brand_attr = $('attributes').first().json.brand_attribute
  if (brand_attr?.code) {
    attrs.push(brand_attr)
  }
  return new Map(attrs.map(attr => [attr.code, attr]))
})()

const found_req_attrs = (() => {
  const ai_found = $('Attributes').first().json.output
    .filter(o => o.values.length)
  const brand_id_found = (() => {
    try {
      const found = $('brand').first().json.found_attr_id
      return found
    } catch (error) {
      return ""
    }
  })()
  if (brand_id_found) {
    ai_found.push({
      "code": "brand",
      "values": [String(brand_id_found)]
    })
  }
  return ai_found
})()

// @ts-ignore
const attributes = {};
(() => {
  found_req_attrs
    .forEach(attr => {
      const found_info = required_attrs_map.get(attr.code)
      const value_type = found_info?.value_type ?? ""
      if (["multiselect"].includes(value_type)) {
        // @ts-ignore
        attributes[attr.code] = attr.values.map(v => Number(v))
      } else {
        // @ts-ignore
        attributes[attr.code] = Number.isNaN(Number(attr.values[0])) ? String(attr.values[0]) : Number(attr.values[0])
      }
    })
})()

// @ts-ignore
const images = {};
(() => {
  const urls = $input.first().json.image_urls
  if (urls.length > 2) urls.length = 2
  urls.forEach((url, i) => {
    if (i === 0) {
      // @ts-ignore
      images.main = url
    } else {
      const key_value = String(i - 1)
      // @ts-ignore
      images[key_value] = url
    }
  })
})();

const category_ids = $('category').first().json.category.codes
.map(id => Number(id));

const offer = (() => {
  const seller_product_code  = $('odoo_product').first().json.product.sku
  // 1 - Active
  const status = 1
  const price = $('odoo_product').first().json.product.price
  const min_selling_price = $('odoo_product').first().json.product.price
  // НДС принимается только либо 21, либо 11, иначе ошибка импорта
  const vat = (() => {
    const tax_odoo = $('odoo_product').first().json.product.tax_percent
    if (tax_odoo === 19) return 21
    if (tax_odoo < 19) return 11
    return tax_odoo
  })()
  const min_delivery_interval = 5
  const max_delivery_interval = 5
  const stock = Math.round($('odoo_product').first().json.product.stock)
  return {
    seller_product_code,
    status,
    price,
    min_selling_price,
    vat,
    min_delivery_interval,
    max_delivery_interval,
    stock
  }
})()

const product = {
  attribute_set_id: Number($('attributes').first().json.attributes_set_id),
  category_ids: category_ids,
  ean: $('odoo_product').first().json.product.ean,
  name: $('odoo_product').first().json.product.title,
  // ВЕРНУТЬ
  description: removeImagesFromHTML($('odoo_product').first().json.product.description),
  // description: "This is a sample description text that contains enough words and characters to meet the minimum length requirement of fifty symbols.",
  attributes: attributes,
  images: images,
  offer: offer
}

const products = {
  "0": product
}

return {products}

const response = $input.first().json

const is_success = ["success", "partial_success"].includes(response.status)
const product_id = response?.data?.product?.[0] ?? ""
const offer_id = response?.data?.offer?.[0] ?? ""
const is_product_id_exist = !!product_id
const is_offer_id_exist = !!offer_id
const message = response?.message?.join() ?? response?.error?.message ?? ""

const is_already_exists = $input.first().json?.error?.message?.includes("already exists for product with id")

const existing_product_id = (() => {
  if (!is_already_exists) return ""
  const msg = $input.first().json.error.message
  const match = msg.match(/id\s([a-f0-9]{24})/);
  const id = match ? match[1] : "";
  return id
})()

return {is_already_exists, existing_product_id, is_success, product_id, offer_id, is_product_id_exist, is_offer_id_exist, message}

