(() => {
const errorString = $json.message

const match = errorString.match(/^(\d+)\s*-\s*"(.+)"$/);

if (match) {
  const code = match[1];
  const jsonString = match[2];

  const unescapedJson = jsonString.replace(/\\"/g, '"');

  const parsed = JSON.parse(unescapedJson);

  const message = parsed.message.product[0];

  return `code: ${code}, ${message}`
} else {
  return ""
}
})()
}}

