const is_images_found = image_urls.length > 0

return {image_urls, is_images_found}

const odoo_product = $('odoo_product').first().json.product

const {
  main_image_base,
  add_image_bases,
  gpsr_image_base
} = odoo_product

const images = [
  {
    image_1920: main_image_base
  },
  ...add_image_bases
]

if (gpsr_image_base) {
  images.push({
    image_1920: gpsr_image_base
  })
}


const imagesJson = images
  .map(img => {
  return {
    json: img
  }
})

return imagesJson
